ByteVector extract_subrange(const ByteVector& vec, uint index, uint length) {
    if (index > vec.size()) {
        return ByteVector();
    }

    uint remaining = vec.size() - index;
    uint copy_length = (length < remaining) ? length : remaining;

    ByteVector result;
    result.reserve(copy_length);
    for (uint i = 0; i < copy_length; ++i) {
        result.push_back(vec[index + i]);
    }

    return result;
}
